#pragma once
#include "kstationNativeMidiInit.h"
#include <array>
#include <type_traits>
#include <variant>
namespace kstation {
class NativeMidiInitOwner final {
 using M=NativeMidiInit;using S=NativeMidiSerialEnable;using U=NativeMidiUtility;using X=NativeMidiTxReset;using P=NativeMidiParserInit;using C=NativeMidiChannelInit;using F=NativeMidiFill16;using H=NativeMidiHeldInit;using G=NativeMidiGlobalsInit;using Job=std::variant<std::monostate,M,S,U,X,P,C,F,H,G>;
public:struct CodeRange{uint32_t begin,end;};inline static constexpr std::array<CodeRange,6>CodeRanges{{{0x9d0,0xa02},{0xad6,0xaf4},{0x251a,0x252c},{0x279c,0x27b6},{0x2904,0x2954},{0x2ce8,0x2d38}}};static bool candidate(uint32_t pc){for(auto r:CodeRanges)if(pc>=r.begin&&pc<r.end)return true;return false;}void reset(){for(auto&j:jobs_)j.emplace<std::monostate>();depth_=0;}bool active()const{return depth_!=0;}
 bool step(Stage1Cpu&c){if(midi_projection::blocked(c))return false;for(unsigned n=0;n<jobs_.size()+1;++n){if(!depth_){if(uint32_t(c.getPC())==0x251a)jobs_[depth_++].emplace<M>();else if(uint32_t(c.getPC())==0x9d0)jobs_[depth_++].emplace<S>();else return false;}auto&j=jobs_[depth_-1];if(awaiting(j)){if(resume(j,c)){if(complete(j)){j.emplace<std::monostate>();--depth_;}continue;}if(!pushChild(c,j))return false;continue;}bool ok=std::visit([&](auto&v)->bool{using V=std::decay_t<decltype(v)>;if constexpr(std::is_same_v<V,std::monostate>)return false;else return v.step(c);},j);if(!ok)return false;if(complete(j)){j.emplace<std::monostate>();--depth_;}return true;}return false;}
private:static bool awaiting(const Job&j){if(auto*p=std::get_if<M>(&j))return p->task().awaitingChild();if(auto*p=std::get_if<S>(&j))return p->task().awaitingChild();if(auto*p=std::get_if<P>(&j))return p->task().awaitingChild();if(auto*p=std::get_if<C>(&j))return p->task().awaitingChild();return false;}static bool complete(const Job&j){return std::visit([](const auto&v)->bool{using V=std::decay_t<decltype(v)>;if constexpr(std::is_same_v<V,std::monostate>)return true;else return v.task().complete();},j);}static bool resume(Job&j,Stage1Cpu&c){if(auto*p=std::get_if<M>(&j))return p->resumeChild(c);if(auto*p=std::get_if<S>(&j))return p->resumeChild(c);if(auto*p=std::get_if<P>(&j))return p->resumeChild(c);if(auto*p=std::get_if<C>(&j))return p->resumeChild(c);return false;}
 bool pushChild(Stage1Cpu&c,const Job&parent){if(depth_==jobs_.size())return false;auto&j=jobs_[depth_];if(auto*p=std::get_if<S>(&parent)){if(p->task().child()==MidiSerialEnableTask::Child::ResetRx&&uint32_t(c.getPC())==0x9de)j.emplace<U>(MidiUtilityTask::Kind::ResetExternal);else if(p->task().child()==MidiSerialEnableTask::Child::ResetTx&&uint32_t(c.getPC())==0xad6)j.emplace<NativeMidiTxReset>();else return false;}else if(auto*p=std::get_if<M>(&parent)){using X=MidiInitTask::Child;switch(p->task().child()){case X::ResetRx:if(uint32_t(c.getPC())!=0x9de)return false;j.emplace<U>(MidiUtilityTask::Kind::ResetExternal);break;case X::ResetTx:if(uint32_t(c.getPC())!=0xad6)return false;j.emplace<NativeMidiTxReset>();break;case X::ResetInternal:if(uint32_t(c.getPC())!=0x279c)return false;j.emplace<U>(MidiUtilityTask::Kind::ResetInternal);break;case X::ResetParser:if(uint32_t(c.getPC())!=0x2904)return false;j.emplace<P>();break;}}else if(auto*p=std::get_if<P>(&parent)){using X=MidiParserInitTask::Child;switch(p->task().child()){case X::Channels:if(uint32_t(c.getPC())!=0x2ce8)return false;j.emplace<C>();break;case X::Held:if(uint32_t(c.getPC())!=0x2d1a)return false;j.emplace<H>();break;case X::Globals:if(uint32_t(c.getPC())!=0x2930)return false;j.emplace<G>();break;}}else if(std::holds_alternative<C>(parent)){if(uint32_t(c.getPC())!=0x2948)return false;j.emplace<F>(uint32_t(c.reg32(1)),uint8_t(c.reg8(8)));}else return false;++depth_;return true;}
 std::array<Job,4>jobs_{};unsigned depth_=0;
};
}
